package com.luci.pianoroom;
import java.util.*;
/** Bounded retrospective performance with the controllers and notes at its start. */
public final class MidiHistory {
 private final ArrayDeque<MidiTape.Event> events=new ArrayDeque<>();private final int[][] keys=new int[16][128],sounding=new int[16][128];private final int[] pedal=new int[16],pitch=new int[16];public boolean enabled;
 public MidiHistory(){Arrays.fill(pitch,8192);}
 public synchronized void enable(boolean on){enabled=on;if(!on){events.clear();for(int[] a:keys)Arrays.fill(a,0);for(int[] a:sounding)Arrays.fill(a,0);Arrays.fill(pedal,0);Arrays.fill(pitch,8192);}}
 public synchronized void add(int s,int a,int b){if(!enabled)return;long t=System.nanoTime()/1000;int type=s&240;if(type!=128&&type!=144&&type!=176&&type!=224&&type!=192)return;events.addLast(new MidiTape.Event(t,s,a,b));while(!events.isEmpty()&&(events.size()>65536||events.peekFirst().micros<t-65000000))apply(events.removeFirst(),keys,sounding,pedal,pitch);}
 private static void apply(MidiTape.Event e,int[][] keys,int[][] sounding,int[] pedal,int[] pitch){int ch=e.status&15,k=e.status&240;if(k==144&&e.b>0){keys[ch][e.a]=sounding[ch][e.a]=e.b;}else if(k==128||k==144){keys[ch][e.a]=0;if(pedal[ch]<64)sounding[ch][e.a]=0;}else if(k==224)pitch[ch]=e.a|(e.b<<7);else if(k==176){if(e.a==64){pedal[ch]=e.b;if(e.b<64)for(int n=0;n<128;n++)if(keys[ch][n]==0)sounding[ch][n]=0;}else if(e.a==120||e.a==123){Arrays.fill(keys[ch],0);Arrays.fill(sounding[ch],0);}else if(e.a==121){pedal[ch]=0;pitch[ch]=8192;for(int n=0;n<128;n++)if(keys[ch][n]==0)sounding[ch][n]=0;}}}
 public synchronized List<MidiTape.Event> snapshot(long endMicros,long duration){long begin=endMicros-duration;int[][] k=new int[16][128],s=new int[16][128];for(int i=0;i<16;i++){k[i]=keys[i].clone();s[i]=sounding[i].clone();}int[] p=pedal.clone(),b=pitch.clone();for(MidiTape.Event e:events)if(e.micros<begin)apply(e,k,s,p,b);List<MidiTape.Event> out=new ArrayList<>();for(int ch=0;ch<16;ch++){out.add(new MidiTape.Event(0,176|ch,64,p[ch]));out.add(new MidiTape.Event(0,224|ch,b[ch]&127,b[ch]>>7));for(int note=0;note<128;note++)if(s[ch][note]>0){out.add(new MidiTape.Event(0,144|ch,note,s[ch][note]));if(k[ch][note]==0)out.add(new MidiTape.Event(0,128|ch,note,0));}}for(MidiTape.Event e:events)if(e.micros>=begin&&e.micros<=endMicros)out.add(new MidiTape.Event(e.micros-begin,e.status,e.a,e.b));return out;}
}
